// ── 증분 색인의 판단부 ────────────────────────────────────────────────────
// 볼트 전체를 매번 읽되, 내용이 바뀐 파일만 임베딩으로 내려보낸다.
// 파일 읽기는 싸고(80개 ~100ms) Ollama 임베딩이 비싸다.
//
// [흐름]  Fetch Manifest(DB 의 현재 색인) + Read Vault Files(볼트 원본)
//          → 여기서 해시 대조 → Route 가 종류별로 가른다
//
// [출력 — 두 종류다]  Route 가 json.kind 로 가르므로 이름을 바꾸면 배선이 깨진다.
//   kind:'file'   바뀐 파일 1건씩. binary 를 재첨부해 Data Loader 가 읽는다
//                 → Obsidian Vector Store 로 가서 다시 임베딩된다
//   kind:'sweep'  맨 끝 1건. 지금 볼트에 있는 전체 목록(keep)
//                 → Sweep 이 이 목록에 없는 청크를 지운다(삭제된 노트 정리)
//
// [주의] 이 노드가 빈 keep 을 내보내면 Sweep 이 인덱스를 통째로 지운다.
//        그래서 아래에서 keep 이 비면 던져서 멈춘다.

const VAULT = '/home/node/vault';

// ── 색인 제외 ──────────────────────────────────────────────────────────────
// 기계가 만든 노트는 색인하지 않는다.
// `rag-unanswered.md` 는 ⑤ 가 쌓는 **못 답한 질문의 원문 로그**다. 이걸 색인에 두면
// "왜 못 답했지?" 류의 질문에 봇이 자기 실패 로그를 근거로 집는 자기참조 고리가 생긴다
// (2026-09-18 실측: 과거 거절 19건 중 **10건**에서 BM25 1위. dense 는 이 노트를 잘 안
// 집어서 지금은 잠복해 있고, 어휘 채널을 켜는 날 드러난다).
// 여기서 `continue` 하면 keep 에도 안 들어가므로 Sweep 이 기존 청크를 지운다 —
// 제외 목록에 넣는 것만으로 색인에서 빠진다.
const EXCLUDE = new Set(['rag-unanswered.md']);

// cyrb53 — 53비트 해시. 이 인스턴스는 태스크 러너에 crypto 모듈을 허용해두지
// 않아(N8N_RUNNERS_ALLOWED_BUILT_IN_MODULES 미설정) require('crypto')가 막힌다.
// 개인 노트 변경 감지용이라 충돌 확률은 무시할 수 있다.
function hash53(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}

// 이미 색인돼 있는 것: { relPath: hash }
let manifest = {};
try {
  manifest = $('Fetch Manifest').first().json.manifest || {};
} catch (e) {
  manifest = {}; // 테이블 없음/조회 실패 → 전체 재색인
}

const items = $input.all();
const keep = {};
const changed = [];

for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) continue;

  // 파일명만 쓰면 다른 폴더의 동명 노트가 충돌한다. 볼트 기준 상대경로를 쓴다.
  const dir = String(bin.directory || '').replace(/\/+$/, '');
  const relPath = (dir + '/' + bin.fileName).replace(VAULT, '').replace(/^\/+/, '');

  if (EXCLUDE.has(relPath)) continue;   // keep 에 안 넣는다 → Sweep 이 지운다

  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const h = hash53(buf.toString('utf-8'));

  keep[relPath] = h;

  if (manifest[relPath] !== h) {
    changed.push({
      json: {
        kind: 'file',
        relPath,
        title: String(bin.fileName).replace(/\.md$/, ''),
        hash: h,
        bytes: bin.bytes,
      },
      binary: items[i].binary, // 재첨부 안 하면 Data Loader가 읽을 게 없다
      pairedItem: { item: i },
    });
  }
}

// 볼트를 하나도 못 읽었으면 인덱스를 건드리지 않고 실패시킨다.
// 마운트가 끊겼을 때 Sweep이 인덱스 전체를 지워버리는 걸 막는 안전장치다.
if (Object.keys(keep).length === 0) {
  throw new Error('볼트에서 .md 파일을 하나도 읽지 못했다. /home/node/vault 마운트를 확인할 것. 인덱스는 손대지 않았다.');
}

const stale = Object.keys(manifest).filter((s) => !(s in keep));

return [
  ...changed,
  {
    json: {
      kind: 'sweep',
      keep,
      stats: {
        vaultFiles: Object.keys(keep).length,
        alreadyIndexed: Object.keys(manifest).length,
        changed: changed.length,
        stale: stale.length,
        staleList: stale.slice(0, 20),
      },
    },
  },
];

parameters.query:
WITH keep AS (
  SELECT key AS source, value AS hash
  FROM jsonb_each_text(convert_from(decode($1, 'base64'), 'UTF8')::jsonb)
)
DELETE FROM n8n_vectors v
WHERE NOT EXISTS (
  SELECT 1 FROM keep k
  WHERE k.source = v.metadata->>'source'
    AND k.hash   = v.metadata->>'hash'
);
